three={'A':'Ala','R':'Arg','N':'Asn','D':'Asp','C':'Cys','Q':'Gln','E':'Glu','G':'Gly','H':'His','I':'Ile','L':'Leu','K':'Lys','M':'Met','F':'Phe','P':'Pro','S':'Ser','T':'Thr','W':'Trp','Y':'Tyr','V':'Val'}
peps={
 'trp-cage 1L2Y':('NLYIQWLKDGGPSSGRPPPS','T'),
 'villin 1VII':('MLSDEDFKAVFGMTRSAFANLPLWKQQNLKKEKGLF','T'),
 'insulin A':('GIVEQCCTSICSLYQLENYCN','T'),
 'insulin B':('FVNQHLCGSHLVEALYLVCGERGFFYTPKT','N'),
 'beta-endorphin':('YGGFMTSEKSQTPLVTLFKNAIIKNAYKKGE','T'),
 'ubiquitin 1UBQ':('MQIFVKTLTGKTITLEVEPSDTIENVKAKIQDKEGIPPDQQRLIFAGKQLEDGRTLSDYNIQKESTLHLVLRLRGG','F'),
}
def loops(w):
    n=len(w); idx=[i for i,g in enumerate(w) if g in '∈∋']
    seq=[(i,w[i]) for i in idx]; stack=[]; out=[]
    for i,g in seq+[(i+n,g) for i,g in seq]:
        if g=='∈': stack.append(i)
        elif stack:
            s=stack.pop()
            if s<n: out.append(i-s-1)
    return out
def law(w):
    c=Counter(w); b=c['∈']-c['∋']
    if b>0: return 'B'
    if b<0: return 'F'
    L=loops(w)
    return 'T' if any(x>0 for x in L) else 'N'
