    m=re.search(r'word\s*\n\s*(\S+)',out)
    w=m.group(1) if m else ''.join(g for g in out if g in '⊢⊣≻≺⋈⊤⊥∈∋⊙⊞◻')
    c=Counter(w)
    print(f"{name}")
