    print(f"  ∈(Asn)={c['∈']} ∋(Gln)={c['∋']}  bal={c['∈']-c['∋']:+d}  loops enclose {loops(w)}")
    print(f"  law says {law(w)}   sweep(PDB) says {sweep}   {'AGREE' if law(w)==sweep else 'DIFFER'}")
