cd ~/imsgct/Vox && python3 - <<'PY'
import genetic_table as gt, random, subprocess, re, glob, os
from collections import Counter
random.seed(0)
back={}
for c,(k,v) in gt.CODON.items():
    if k=='aa': back.setdefault(v,[]).append(c)
A3={'ALA':'Ala','ARG':'Arg','ASN':'Asn','ASP':'Asp','CYS':'Cys','GLN':'Gln','GLU':'Glu','GLY':'Gly','HIS':'His','ILE':'Ile','LEU':'Leu','LYS':'Lys','MET':'Met','PHE':'Phe','PRO':'Pro','SER':'Ser','THR':'Thr','TRP':'Trp','TYR':'Tyr','VAL':'Val'}
def seq_from_pdb(p):
    out=[];seen=set()
    for l in open(p,errors='ignore'):
        if l.startswith('ATOM') and l[12:16].strip()=='CA':
            k=(l[21],l[22:27]);
            if k in seen: continue
            seen.add(k); r=l[17:20].strip().upper()
            if r in A3: out.append(A3[r])
            else: out.append(None)
    return out
def loops(w):
    n=len(w); idx=[i for i,g in enumerate(w) if g in '∈∋']
    seq=[(i,w[i]) for i in idx]; stack=[]; out=[]
    for i,g in seq+[(i+n,g) for i,g in seq]:
        if g=='∈': stack.append(i)
        elif stack:
            s=stack.pop()
            if s<n: out.append(i-s-1)
    return out
def law(w):
    c=Counter(w); b=c['∈']-c['∋']
    if b>0: return 'B'
    if b<0: return 'F'
    return 'T' if any(x>0 for x in loops(w)) else 'N'
targets={'1L2Y':'T','1VII':'T','3I40':'T','1UBQ':'F','1EMA':'B','insulin_b_chain_platonic':'N','beta_endorphin_platonic':'T','pbp2a_binder_s179':'T','pbp2a_binder_s590':'F'}
files={}
for p in glob.glob(os.path.expanduser('~/imsgct/red-hot_rebis/**/*.pdb'),recursive=True):
    b=os.path.basename(p)[:-4]
    if b in targets and b not in files: files[b]=p
print(f"{'protein':26} {'RNA nt':>7} {'word len':>8} {'∈':>3} {'∋':>3} {'bal':>4}  law  sweep")
for b,sw in targets.items():
    if b not in files: print(f"{b:26} (pdb not found)"); continue
    aas=[a for a in seq_from_pdb(files[b]) if a]
    rna='AUG'+''.join(random.choice(back[a]) for a in aas)+'UAA'
    out=subprocess.run(['python3','vox.py','--rna',rna],capture_output=True,text=True).stdout
    m=re.search(r'^word\s+(\S+)',out,re.M); w=m.group(1) if m else ''
    v=re.search(r'^verdict\s+(\S+)',out,re.M)
    c=Counter(w)
    print(f"{b:26} {len(rna):7d} {len(w):8d} {c['∈']:3d} {c['∋']:3d} {c['∈']-c['∋']:+4d}  {law(w):3}  {sw}  vox={v.group(1) if v else '?'}  {'AGREE' if law(w)==sw else 'DIFFER'}")
PY

