import genetic_table as gt
inv={v[0]:(k,v[1]) for k,v in gt.AA_GLYPH.items()}
promoted={k for k in gt.AA_GLYPH}
rows=[]
for c,(k,v) in sorted(gt.CODON.items()):
    if k=='aa' and v in promoted:
        rows.append((c,v,gt.AA_GLYPH[v][0],gt.AA_GLYPH[v][1]))
print(len(rows),'promoted codons of 61 sense codons')
from collections import defaultdict
d=defaultdict(list)
for c,v,g,f in rows: d[(g,v,f)].append(c)
for (g,v,f),cs in sorted(d.items(), key=lambda x:gt.AA_GLYPH[x[0][1]][2]):
